sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    /*
        If overriding duplicate validation for table extensions, create table specific BRs (with lower order than base table duplicate validation BRs) and set flag current._skip_duplicate_validation=true to skip running duplicate validation BRs of base table.
    */
      if (current.account && current.type && current.type.entity_type == global.CSMBaseConstants.ACCOUNT_TABLE) {
              var rec = new GlideRecord(global.CSMBaseConstants.SOLD_PRODUCT_RELATED_PARTY);
              rec.addQuery('sold_product', current.sold_product);
              rec.addQuery('account', current.account);
              if (current.operation() == "update" && current.type.changes() && !current.account.changes() && !current.sold_product.changes()) {
                  rec.addQuery('type', current.type);
              }
              rec.addNullQuery('contact'); // Not considering account as duplicate for record-keeping purpose if contact is also populated
              rec.addNullQuery('consumer'); // Not considering account as duplicate for record-keeping purpose if consumer is also populated
              rec.setLimit(1);
              rec.query();
              if (rec.hasNext()) {
                  gs.addErrorMessage(gs.getMessage('The sold product is already available for the account'));
                  current.setAbortAction(true);
              }
      }
  })(current, previous);
